select json_build_object('rows',(select count(*) from document_templates),'cats',(select json_agg(json_build_object('c',doc_category,'n',n,'last',l) order by n desc) from(select doc_category,count(*)n,max(last_confirmed_date)l from document_templates group by 1)q where n>=5),'samples',(select json_agg(sample_source) from(select distinct sample_source from document_templates where doc_category like '%중복선정%' order by 1 desc limit 3)q))j;
